18	
19	/**
20	 * Formats a person's stored first and last names into a single display string.
21	 */
22	public final class PersonNameFormatter {
23	
24	    private PersonNameFormatter() {
25	    }
26	
27	    /**
28	     * Format the given names as {@code "LastName, FirstName"}.
29	     *
30	     * @param firstName the first name (may be {@code null})
31	     * @param lastName the last name (may be {@code null})
32	     * @return the names formatted as {@code "LastName, FirstName"}
33	     */
34	    public static String displayName(String firstName, String lastName) {
35	        return lastName + ", " + firstName;
36	    }
37	
38	    /**
39	     * Format the upper-cased first letters of the given names as {@code "F.L."}.
40	     *
41	     * @param firstName the first name
42	     * @param lastName the last name
43	     * @return the initials formatted as {@code "F.L."}
44	     */
45	    public static String initials(String firstName, String lastName) {
46	        return initial(firstName) + initial(lastName);
47	    }
48	
49	    private static String initial(String name) {
50	        return Character.toUpperCase(name.charAt(0)) + ".";
51	    }
52	}
